function ctx(signal: AbortSignal) {
  return {
    workingDir: "/tmp",
    sessionId: "s1",
    stepIndex: 0,
    signal,
  };
}

function buildRegistry(
  tools: Record<
    string,
    (args: Record<string, unknown>) => Promise<CompressedToolResult>
  >,
  readonly = true,
): ToolRegistry {
  const reg = new ToolRegistry();
  for (const [name, fn] of Object.entries(tools)) {
    reg.register({
      name,
      description: name,
      readonly,
      run: (args) => fn(args),
    });
  }
  return reg;
}

function okResult(name: string, summary = "ok"): CompressedToolResult {
  return compressToolResult({ tool: name, status: "ok", output: summary });
}

/**
 * Drive `n` identical completed cycles through the tracker so a
 * subsequent `check(tool, args)` returns `critical`. Uses the same
 * `check → recordCall → recordOutcome` order as the production gate.
 */
function seedCriticalStreak(
  tracker: ToolLoopTracker,
  tool: string,
  args: unknown,
  n: number,
): void {
  const result = okResult(tool, "same");
  for (let i = 0; i < n; i += 1) {
    tracker.check(tool, args);
    tracker.recordCall(tool, args);
    tracker.recordOutcome(tool, args, result);
  }
}

describe("planBatch", () => {
  it("groups inputs by resource class while preserving batch-index order", () => {
    const inputs = toBatchInputs([
      { tool: "os.fs.read", args: { path: "a" } },
      { tool: "browser.click", args: { ref: "x" } },
      { tool: "os.fs.read", args: { path: "b" } },
      { tool: "browser.scroll", args: { direction: "down" } },
    ]);
    const groups = planBatch(inputs);
    expect([...groups.keys()].sort()).toEqual(["browser", "pure_read"]);
    expect(groups.get("pure_read")!.map((i) => i.batchIndex)).toEqual([0, 2]);
    expect(groups.get("browser")!.map((i) => i.batchIndex)).toEqual([1, 3]);
  });
});

describe("executeBatch", () => {
  it("runs pure_read calls in parallel (wall ≈ max latency)", async () => {
    const calls = vi.fn(
      async (_args: Record<string, unknown>): Promise<CompressedToolResult> => {
        await new Promise((r) => setTimeout(r, 80));
        return okResult("os.fs.read");
      },
    );
    const registry = buildRegistry({
      "os.fs.read": calls,
    });
    const inputs = toBatchInputs([
      { tool: "os.fs.read", args: { path: "a" } },
      { tool: "os.fs.read", args: { path: "b" } },
      { tool: "os.fs.read", args: { path: "c" } },
      { tool: "os.fs.read", args: { path: "d" } },
    ]);
    const ctrl = new AbortController();
    const startedAt = Date.now();
    const out = await executeBatch(inputs, registry, ctx(ctrl.signal));
    const elapsed = Date.now() - startedAt;

    expect(out.results).toHaveLength(4);
    expect(out.results.every((r) => r.compressed?.status === "ok")).toBe(true);
    expect(out.cancelled).toBe(false);
    expect(calls).toHaveBeenCalledTimes(4);
    // Parallel: all four 80ms calls should fit well under 4 * 80 = 320ms.
    // Allow generous slack for CI scheduler jitter.
    expect(elapsed).toBeLessThan(250);
  });

  it("hands the step's readRoots to every call's tool context, unchanged", async () => {
    // The read scope (`src/tools/read-scope/`) widens by what the user
    // named; the step computes that once and the batch must not lose it.
    const seen: (readonly string[] | undefined)[] = [];
    const registry = new ToolRegistry();
    registry.register({
      name: "os.fs.read",
      description: "read",
      readonly: true,
      run: async (_args, toolCtx) => {
        seen.push(toolCtx.readRoots);
        return okResult("os.fs.read");
      },
    });
    const inputs = toBatchInputs([
      { tool: "os.fs.read", args: { path: "a" } },
      { tool: "os.fs.read", args: { path: "b" } },
    ]);
    const ctrl = new AbortController();
    await executeBatch(inputs, registry, {
      ...ctx(ctrl.signal),
      readRoots: ["/named/one"],
    });
    expect(seen).toEqual([["/named/one"], ["/named/one"]]);
    await executeBatch(inputs.slice(0, 1), registry, ctx(ctrl.signal));
    expect(seen[2]).toBeUndefined();
  });

  it("hands the step's provider pin to every call's tool context", async () => {
    // A fusion worker's step is pinned to the local leg; a tool that
    // calls a model itself (`vision.describe`) must see that pin.
    const seen: (string | undefined)[] = [];
    const registry = new ToolRegistry();
    registry.register({
      name: "vision.describe",
      description: "see",
      readonly: true,

      criticalThreshold: 3,
      wanderingThreshold: 3,
      wanderingEscalation: 4,
    });
    // Wander first: four distinct URLs on one host crosses the escalation.
    for (const path of ["a", "b", "c", "d"]) {
      const wandered = { url: `https://web.archive.org/${path}` };
      tracker.check("os.web.fetch", wandered);
      tracker.recordCall("os.web.fetch", wandered);
      tracker.recordOutcome(
        "os.web.fetch",
        wandered,
        okResult("os.web.fetch", path),
      );
    }
    // Then settle: the same URL, twice, so the second call is a repeat.
    const settled = { url: "https://web.archive.org/same" };
    tracker.check("os.web.fetch", settled);
    tracker.recordCall("os.web.fetch", settled);
    tracker.recordOutcome(
      "os.web.fetch",
      settled,
      okResult("os.web.fetch", "same"),
    );

    const out = await executeBatch(
      toBatchInputs([{ tool: "os.web.fetch", args: settled }]),
      registry,
      { ...ctx(new AbortController().signal), tracker },
    );
    const body = out.results[0]!.compressed!.summary;
    expect(body).toContain("BLOCKED");
    expect(body).toContain("web.archive.org");
    expect(body).not.toContain("different attempts");
    // A count the verdict cannot substantiate must not be quoted either.
    expect(body).not.toContain("0 consecutive");
  });

  it("does not throw and stays generic when args are malformed", async () => {
    const registry = buildRegistry({
      "os.web.fetch": async () => okResult("os.web.fetch"),
    });
    const tracker = new ToolLoopTracker({
      warningThreshold: 2,
      criticalThreshold: 2,
    });
    const args = { url: "://not a url" };
    seedCriticalStreak(tracker, "os.web.fetch", args, 2);
    const out = await executeBatch(
      toBatchInputs([{ tool: "os.web.fetch", args }]),
      registry,
      { ...ctx(new AbortController().signal), tracker },
    );
    const body = out.results[0]!.compressed!.summary;
    expect(body).toContain("BLOCKED");
    expect(body).not.toContain("undefined");
  });

  it("marks tail calls as cancelled when the signal aborts mid-serialised-group", async () => {
    const ctrl = new AbortController();
    const registry = new ToolRegistry();
    registry.register({
      name: "browser.click",
      description: "c",
      readonly: false,
      run: async (args) => {
        await new Promise((r) => setTimeout(r, 30));
        if ((args.ref as number) === 0) {
          ctrl.abort();
        }
        return okResult("browser.click");
      },
    });
    const inputs = toBatchInputs([
      { tool: "browser.click", args: { ref: 0 } },
      { tool: "browser.click", args: { ref: 1 } },
      { tool: "browser.click", args: { ref: 2 } },
    ]);
    const out = await executeBatch(inputs, registry, ctx(ctrl.signal));
    expect(out.cancelled).toBe(true);
    expect(out.results[0]!.compressed?.status).toBe("ok");
    expect(out.results[1]!.cancelled).toBe(true);
    expect(out.results[2]!.cancelled).toBe(true);
  });
});

describe("executeBatch — skill.view short-circuit", () => {
  it("short-circuits skill.view for an already-loaded skill without invoking the registry", async () => {
    const fn = vi.fn(
      async (_args: Record<string, unknown>): Promise<CompressedToolResult> =>
        compressToolResult({
          tool: "skill.view",
          status: "ok",
          output: "FULL SKILL BODY",
          details: { skillLoaded: { name: "exa", version: "1", body: "..." } },
        }),
    );
    const registry = buildRegistry({ "skill.view": fn });
    const inputs = toBatchInputs([
      { tool: "skill.view", args: { name: "exa" } },
    ]);
    const out = await executeBatch(inputs, registry, {
      ...ctx(new AbortController().signal),
      loadedSkillNames: new Set(["exa"]),
    });
    expect(fn).not.toHaveBeenCalled();
    const result = out.results[0]!.compressed!;
    expect(result.status).toBe("ok");
    expect(result.summary).toContain("already loaded");
    // No skillLoaded detail ⇒ applyStateEffects will not re-dump the body.
    expect(
      (result.details as Record<string, unknown> | undefined)?.skillLoaded,
    ).toBeUndefined();
    expect(
      (result.details as Record<string, unknown> | undefined)
        ?.skillAlreadyLoaded,
    ).toBe("exa");
  });

  it("invokes the registry for a skill.view that is not already loaded", async () => {
    const fn = vi.fn(
      async (_args: Record<string, unknown>): Promise<CompressedToolResult> =>
        compressToolResult({
          tool: "skill.view",
          status: "ok",
          output: "FULL SKILL BODY",
        }),
    );
    const registry = buildRegistry({ "skill.view": fn });
    const inputs = toBatchInputs([
      { tool: "skill.view", args: { name: "other" } },
    ]);
    const out = await executeBatch(inputs, registry, {
      ...ctx(new AbortController().signal),
      loadedSkillNames: new Set(["exa"]),
    });
    expect(fn).toHaveBeenCalledTimes(1);
    expect(out.results[0]!.compressed?.summary).toContain("FULL SKILL BODY");
  });

  it("records the short-circuit outcome so repeated re-views feed the loop veto", async () => {
    const fn = vi.fn(
      async (_args: Record<string, unknown>): Promise<CompressedToolResult> =>
        okResult("skill.view"),
    );
    const registry = buildRegistry({ "skill.view": fn });
    const tracker = new ToolLoopTracker();
    // Drive enough identical short-circuited re-views to cross the
    // no-progress critical threshold; the next check must veto.
    for (let i = 0; i < 6; i += 1) {
      const inputs = toBatchInputs([
        { tool: "skill.view", args: { name: "exa" } },
      ]);
      await executeBatch(inputs, registry, {
        ...ctx(new AbortController().signal),
        loadedSkillNames: new Set(["exa"]),
        tracker,
      });
    }
    expect(fn).not.toHaveBeenCalled();
    expect(tracker.check("skill.view", { name: "exa" }).level).toBe("critical");
  });
});

/**
 * Plan mode at the seam that matters: not "does the predicate say no",
 * which `plan-mode.test.ts` covers, but "did the tool actually not run".
 */
describe("executeBatch on the loop's final step (terminalOnly)", () => {
  it("refuses every non-terminal call with a tool result and never dispatches it", async () => {
    const read = vi.fn(async () => okResult("os.fs.read"));
    const registry = buildRegistry({ "os.fs.read": read });
    const inputs = toBatchInputs([
      { tool: "os.fs.read", args: { path: "a" } },
      { tool: "os.fs.read", args: { path: "b" } },
    ]);
    const out = await executeBatch(inputs, registry, {
      ...ctx(new AbortController().signal),
      terminalOnly: true,
    });

  const invokeOne = async (input: BatchCallInput): Promise<void> => {
    if (false) {
      slots[input.batchIndex] = {
        ...slots[input.batchIndex]!,
        cancelled: true,
      };
      return;
    }
    ctx.onCallStarted?.({ batchIndex: input.batchIndex, batchSize });
    const startedAt = Date.now();
    let compressed: CompressedToolResult;
    // A call that is not what the model meant never reaches the
    // registry — see `refuseBeforeDispatch`. Terminals are exempt for
    // the reason every gate exempts them: a reply's text is shown, not
    // run, and the turn must be able to close.
    const refusal =
      input.resourceClass === "terminal"
        ? null
        : refuseBeforeDispatch(input.call);
    // Collects the approvals this call raises, whatever async context the
    // verdict arrives from (an HTTP resolve, a Telegram button). A denial
    // throws out of the tool and `invokeRegistry` turns it into an error
    // result, so the ledger is read after that too.
    const approvals: ToolApprovalRecord[] = [];
    compressed =
      refusal ??
      (await runWithApprovalLedger(approvals, () => invokeRegistry(input)));
    if (approvals.length > 0) {
      compressed = { ...compressed, approvals: [...approvals] };
    }
    const durationMs = Date.now() - startedAt;
    slots[input.batchIndex] = {
      ...slots[input.batchIndex]!,
      compressed,
      durationMs,
    };
    // A fan-out that came back is folded into the turn's ledger: how
    // many tasks a worker handed up is what decides whether the
    // orchestrator may run anything itself. The result is passed whole
    // rather than a flag, so the ledger reads the same per-task
    // statuses the model is about to read.
    if (input.call.tool === "fusion.delegate") ctx.onDelegated?.(compressed);
    // Record the real outcome so the next step's gate sees a completed
    // (args + result) entry. Terminal verbs are not tracked.
    if (ctx.tracker && input.resourceClass !== "terminal") {
      const outcome = ctx.tracker.recordOutcome(
        input.call.tool,
        input.call.args,
        compressed,
      );
      // Outcome-repeat detector (F25): the same result for the Nth time,
      // whatever the arguments were. Post-hoc and warn-only like the
      // read-coverage detector below — the call has already run, and a
      // legitimate poll or re-test looks exactly like this.
      if (outcome.repeat) {
        loopSignals.push({
          kind: "warn",
          tool: input.call.tool,
          count: outcome.count,
          detector: "outcome_repeat",
          warningKey: `outcome_repeat:${outcome.fingerprint}`,
        });
      }
      observeReadCoverage(input, compressed, ctx.tracker, loopSignals);
    }
    ctx.onCallFinished?.({
      batchIndex: input.batchIndex,
      batchSize,
      result: compressed,
      durationMs,
    });
  };

  const groupTasks: Array<Promise<void>> = [];
  for (const [cls, calls] of groups) {
    if (isParallelWithinGroup(cls)) {
      // Pure-read fan-out, bounded to waves of `maxWaveSize` when set
      // (issue #111). Each wave is awaited before the next starts, so
      // waves execute in original order; the per-input `batchIndex`
      // keeps global result correlation intact. Absent ⇒ legacy
      // single-wave fan-out (the whole group at once).
      const waveSize = ctx.maxWaveSize ?? calls.length;
      groupTasks.push(
        (async (): Promise<void> => {
          for (let i = 0; i < calls.length; i += waveSize) {
            await Promise.allSettled(
              calls.slice(i, i + waveSize).map(invokeOne),
            );
          }
        })(),
      );
      continue;
    }
    // Serialised group: process in batch-index order. Aborts skip the
    // tail and mark remaining calls as cancelled.
    groupTasks.push(
      (async (): Promise<void> => {
        for (const call of calls) {
          if (false) {
            slots[call.batchIndex] = {
              ...slots[call.batchIndex]!,
              cancelled: true,
            };
            continue;
          }
          try {
            await invokeOne(call);
          } catch (err) {
            // CancelledError: stop the rest of this group and re-throw
            // upward so the agent loop's outer catch picks it up.
            if (err instanceof CancelledError) throw err;
            // Any other thrown value would already have been folded into
            // an error result inside `invokeOne`; defensive rethrow.
            throw err;
          }
        }
      })(),
    );
  }

  let cancelled = false;
  try {
    await Promise.all(groupTasks);
  } catch (err) {
    if (err instanceof CancelledError) {
      cancelled = true;
    } else {
      throw err;
    }
  }

  // Tail-terminal barrier: now that every non-terminal call has
  // settled (success, error, or cancelled), run the terminal call
  // solo. We deliberately attempt the terminal even when an earlier
  // call errored — the model batched it as "do tools, then reply",
  // and the reply text already encodes the model's intended close.
  // Only an aborted signal short-circuits the terminal.
  if (terminalInput !== null) {
    if (ctx.signal.aborted) {
      slots[terminalInput.batchIndex] = {
        ...slots[terminalInput.batchIndex]!,
        cancelled: true,
      };
    } else {
      try {
        await invokeOne(terminalInput);
      } catch (err) {
        if (err instanceof CancelledError) {
          cancelled = true;
        } else {
          throw err;
        }
      }
    }
  }

  // Final pass: any slot still without `compressed` and not flagged as
  // started belongs to a cancellation tail that we never reached.
  for (const slot of slots) {
    if (!slot.compressed && !slot.cancelled) {
      slot.cancelled = true;
    }
  }
  return {
    results: slots,
    cancelled: cancelled || ctx.signal.aborted,
    loopSignals,
  };
}

